    rel: [["/d/meteora/", "מטאורה", "Meteora"], ["/d/corfu/", "קורפו", "Corfu"], ["/d/lefkada/", "לפקדה", "Lefkada"], ["/a/romaniote-jews-ancient-community-greece/", "הקהילה הרומניוטית", "The Romaniote community"], ["/a/greece-in-winter-where-to-go-guide/", "יוון בחורף: לאן לנסוע", "Greece in winter: where to go"]],
